mapper.select:
SELECT c.id, TRIM(p.nombre || ' ' || p.primer_apellido) AS nombreCompleto, p.ci, p.telefono, c.persona_id AS personaId, p.nombre, p.primer_apellido AS primerApellido, p.segundo_apellido AS segundoApellido, p.email, p.fecha_nacimiento AS fechaNacimiento, p.genero, c.usuario_id AS usuarioId, u.username, dir.id AS direccionId, dir.calle, dir.numero, dir.referencia, dir.ciudad_id AS ciudadId, ci.nombre AS ciudadNombre, dir.latitud, dir.longitud FROM cliente c LEFT JOIN persona p ON p.id = c.persona_id AND p.deleted = FALSE LEFT JOIN usuario u ON u.id = c.usuario_id AND u.deleted = FALSE LEFT JOIN direccion dir ON dir.id = p.direccion_id AND dir.deleted = FALSE LEFT JOIN ciudad ci ON ci.id = dir.ciudad_id
c.deleted = FALSE AND (p.nombre ILIKE '%' || #{nombre} '%' OR p.primer_apellido ILIKE '%' || #{nombre} '%') AND p.ci ILIKE '%' || #{ci} '%'
ORDER BY c.created_at DESC LIMIT #{limit} OFFSET #{offset}
